/**
 * Code generation: one resolved `.sanmaime` document -> one Playwright `.spec.ts` file (the
 * counterpart of playwright-bdd turning a `.feature` into a `.spec.js`). See docs/cli.md,
 * "Generated files".
 *
 * Pure string generation: no file system access, no registry lookups. Everything comes from the
 * `ResolvedDocument` (produced by `matchSpecs()` after `loadDefinitions()`), whose definitions carry
 * the callbacks the fixture analysis reads.
 *
 * The output is formatted the way Prettier formats it (print width 100, 2-space indent, trailing
 * commas, the configured quote style), so generated files read like hand-written ones and diff
 * cleanly; the unit tests check that Prettier leaves every generated file unchanged.
 */
import path from 'node:path';
import type { QuoteStyle, ResolvedImportTestFrom } from '../config/types';
import { fixtureNamesOf } from '../runtime/resolve';
import type { Tag } from '../parser';
import type { ElementDefinition } from '../runtime/registry';
import { hasHooks, type DocumentHooks, type HookCall, type HookUsage } from './hooks';
import { tagNames } from './tags';
import {
  expectationTarget,
  type ResolvedCondition,
  type ResolvedConditionRef,
  type ResolvedDocument,
  type ResolvedElement,
  type ResolvedExpectation,
  type ResolvedScreen,
} from './match';

/** First line of every generated file; also how `nimaime-gen` recognises files it may delete. */
export const GENERATED_HEADER_PREFIX = '// Generated by nimaime-gen';

/** The module generated specs import the runtime from. */
export const RUNTIME_MODULE = 'nimaime-han/runtime';

/** Title of the test of an element's unconditional block (its invariants, sanmaime.md §5.4). */
export const UNCONDITIONAL_TEST_TITLE = 'Always';

/**
 * Title of the test of a condition block: `When: A`, or `When: A and B` for a block with
 * `And when: B` (sanmaime.md §5.10). The same in every keyword language.
 */
export function conditionTestTitle(condition: Pick<ResolvedCondition, 'title'>): string {
  return `When: ${condition.title}`;
}

/** Fixture requested for a callback whose fixtures cannot be determined. */
export const FALLBACK_FIXTURE = 'page';

const PRINT_WIDTH = 100;
const INDENT = '  ';

export interface GenerateOptions {
  /** Absolute output directory (`config.outputDir`). */
  outputDir: string;
  /** Absolute config directory; the spec's path relative to it is kept under `outputDir`. */
  configDir: string;
  /** Custom `test` to extend (`config.importTestFrom`); default: `@playwright/test`'s `test`. */
  importTestFrom?: ResolvedImportTestFrom | undefined;
  /** Quote style of string literals (`config.quotes`). */
  quotes: QuoteStyle;
  /** Absolute paths of the definition files, imported for their side effects, in this order. */
  definitionFiles: readonly string[];
  /** The hooks that apply to the document's screens and elements (`documentHooks(doc)`). */
  hooks?: DocumentHooks | undefined;
}

/** One generated test: its title path, e.g. `['Screen: Login', 'Element: Login Form', 'Always']`. */
export interface GeneratedTest {
  titlePath: string[];
  /** Its tags: those of its screen, element and `When:` block, deduplicated (sanmaime.md §5.8). */
  tags: string[];
}

/** A callback whose fixtures could not be determined (see `collectFixtureNames`). */
export interface UnknownFixtures {
  /** E.g. `condition "Logged in"`. */
  callback: string;
  /** The test (or hook, e.g. `[…, 'beforeAll hook']`) that requests `fallback` for it instead. */
  titlePath: string[];
  /** The fixture requested instead; `page` when absent. */
  fallback?: string;
}

export interface GeneratedSpecFile {
  /** Absolute path of the file to write. */
  path: string;
  /** File contents. */
  content: string;
  /** The tests of the file, in order. */
  tests: GeneratedTest[];
  /** Callbacks whose first parameter is not destructured (the test requests `page` for them). */
  unknownFixtures: UnknownFixtures[];
}

// ---------------------------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------------------------

/**
 * Where the spec generated from `specFile` goes: its path relative to `configDir`, under
 * `outputDir`, with `.sanmaime` replaced by `.spec.ts` (`specs/login.sanmaime` ->
 * `<outputDir>/specs/login.spec.ts`). `..` segments (specs outside `configDir`) become `__`, so
 * that every generated file stays inside `outputDir`.
 */
export function generatedSpecPath(specFile: string, configDir: string, outputDir: string): string {
  const relative = path.relative(configDir, specFile);
  const segments = relative
    .split(path.sep)
    .filter((segment) => segment !== '' && !/^[A-Za-z]:$/.test(segment))
    .map((segment) => (segment === '..' ? '__' : segment));
  const base = segments.pop() ?? 'spec.sanmaime';
  const name = base.endsWith('.sanmaime')
    ? `${base.slice(0, -'.sanmaime'.length)}.spec.ts`
    : `${base}.spec.ts`;
  return path.join(outputDir, ...segments, name);
}

/** File extensions left out of import specifiers (resolved by Playwright's loader and by `tsc`). */
const OMITTED_EXTENSIONS = ['.ts', '.tsx', '.js', '.jsx'];

/**
 * The import specifier of `target` from a file in `fromDir`: relative, with `/` separators and
 * starting with `./` or `../`. The `.ts`, `.tsx`, `.js` and `.jsx` extensions are left out (Playwright
 * resolves extensionless imports, as TypeScript's `Bundler` resolution does); other extensions
 * (`.mjs`, `.cjs`, `.mts`, `.cts`) are kept, since an explicit specifier is always unambiguous.
 */
export function importSpecifier(fromDir: string, target: string): string {
  let relative = path.relative(fromDir, target).split(path.sep).join('/');
  const ext = OMITTED_EXTENSIONS.find((e) => relative.endsWith(e) && !relative.endsWith(`.d${e}`));
  if (ext !== undefined) relative = relative.slice(0, -ext.length);
  return relative.startsWith('../') ? relative : `./${relative}`;
}

// ---------------------------------------------------------------------------------------------
// String literals and widths
// ---------------------------------------------------------------------------------------------

/**
 * A JavaScript string literal for `value`, in the preferred quote style unless the value contains
 * more of those quotes than of the other kind (Prettier's rule). Escaping is `JSON.stringify`'s
 * (backslashes, control characters, U+2028/U+2029); other characters, e.g. Japanese, are kept.
 */
export function quote(value: string, style: QuoteStyle): string {
  const preferred = style === 'single' ? "'" : '"';
  const alternate = preferred === "'" ? '"' : "'";
  const count = (ch: string): number => value.split(ch).length - 1;
  const q = count(preferred) > count(alternate) ? alternate : preferred;
  const escaped = JSON.stringify(value)
    .slice(1, -1)
    .replace(/[\u2028\u2029]/g, (ch) => `\\u${ch.charCodeAt(0).toString(16)}`);
  if (q === '"') return `"${escaped}"`;
  // JSON escapes `"`; a single-quoted literal needs `'` escaped instead.
  return `'${escaped.replace(/\\"/g, '"').replace(/'/g, "\\'")}'`;
}

/** Display width as Prettier measures it: East Asian wide / full-width characters count 2. */
export function textWidth(text: string): number {
  let width = 0;
  for (const ch of text) {
    const code = ch.codePointAt(0) ?? 0;
    if (code <= 0x1f || (code >= 0x7f && code <= 0x9f)) continue;
    if (code >= 0x300 && code <= 0x36f) continue;
    width += isWide(code) ? 2 : 1;
  }
  return width;
}

function isWide(code: number): boolean {
  return (
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0x303e) ||
    (code >= 0x3041 && code <= 0x33ff) ||
    (code >= 0x3400 && code <= 0x4dbf) ||
    (code >= 0x4e00 && code <= 0x9fff) ||
    (code >= 0xa000 && code <= 0xa4cf) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xfe30 && code <= 0xfe4f) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6) ||
    (code >= 0x1f300 && code <= 0x1f64f) ||
    (code >= 0x1f900 && code <= 0x1f9ff) ||
    (code >= 0x20000 && code <= 0x3fffd)
  );
}

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

// ---------------------------------------------------------------------------------------------
// A tiny line writer with Prettier-like layout decisions
// ---------------------------------------------------------------------------------------------

class Writer {
  readonly lines: string[] = [];

  constructor(private readonly quotes: QuoteStyle) {}

  q(value: string): string {
    return quote(value, this.quotes);
  }

  line(depth: number, text: string): void {
    this.lines.push(text === '' ? '' : INDENT.repeat(depth) + text);
  }

  blank(): void {
    this.lines.push('');
  }

  fits(depth: number, text: string): boolean {
    return INDENT.length * depth + textWidth(text) <= PRINT_WIDTH;
  }

  /** `key: 'value',` — broken after the colon when it does not fit (Prettier's assignment layout). */
  stringProperty(depth: number, key: string, value: string): void {
    const text = `${key}: ${this.q(value)},`;
    if (this.fits(depth, text)) {
      this.line(depth, text);
    } else {
      this.line(depth, `${key}:`);
      this.line(depth + 1, `${this.q(value)},`);
    }
  }

  /**
   * `callee('title', <params> => {` … `});`. Prettier formats test calls (`test`, `test.describe`)
   * specially: the title and the callback head always stay on the first line, however long; only
   * a destructured parameter that does not fit is broken, one name per line.
   *
   * With `tags`, the call gets a details argument, `callee('title', { tag: [...] }, <params> => {`.
   * Prettier no longer treats a three-argument call whose last argument is a function as a test
   * call: the head stays on one line when it fits, else every argument goes on its own line.
   */
  callWithCallback(
    depth: number,
    callee: string,
    title: string,
    params: { async: boolean; names: string[] | undefined },
    body: (depth: number) => void,
    tags: readonly string[] = [],
  ): void {
    const prefix = params.async ? 'async ' : '';
    const flatParams = params.names === undefined ? '()' : `({ ${params.names.join(', ')} })`;
    if (tags.length > 0) {
      const tagList = tags.map((tag) => this.q(tag));
      const head = `${callee}(${this.q(title)}, { tag: [${tagList.join(', ')}] }, ${prefix}${flatParams} => {`;
      if (this.fits(depth, head)) {
        this.line(depth, head);
        body(depth + 1);
        this.line(depth, '});');
        return;
      }
      this.line(depth, `${callee}(`);
      this.line(depth + 1, `${this.q(title)},`);
      this.tagDetails(depth + 1, tagList);
      this.callbackHead(depth + 1, prefix, params.names, flatParams);
      body(depth + 2);
      this.line(depth + 1, '},');
      this.line(depth, ');');
      return;
    }
    const head = `${callee}(${this.q(title)}, ${prefix}${flatParams} => {`;
    if (params.names === undefined || this.fits(depth, head)) {
      this.line(depth, head);
    } else {
      this.line(depth, `${callee}(${this.q(title)}, ${prefix}({`);
      for (const name of params.names) this.line(depth + 1, `${name},`);
      this.line(depth, '}) => {');
    }
    body(depth + 1);
    this.line(depth, '});');
  }

  /** `async ({ a, b }) => {` as an argument on its own line; a destructuring that does not fit is broken. */
  private callbackHead(
    depth: number,
    prefix: string,
    names: string[] | undefined,
    flatParams: string,
  ): void {
    const head = `${prefix}${flatParams} => {`;
    if (names === undefined || this.fits(depth, head)) {
      this.line(depth, head);
      return;
    }
    this.line(depth, `${prefix}({`);
    for (const name of names) this.line(depth + 1, `${name},`);
    this.line(depth, '}) => {');
  }

  /** `{ tag: ['@a', '@b'] },` as an argument on its own line, broken like Prettier when too long. */
  private tagDetails(depth: number, tagList: readonly string[]): void {
    const array = `[${tagList.join(', ')}]`;
    if (this.fits(depth, `{ tag: ${array} },`)) {
      this.line(depth, `{ tag: ${array} },`);
      return;
    }
    this.line(depth, '{');
    if (this.fits(depth + 1, `tag: ${array},`)) {
      this.line(depth + 1, `tag: ${array},`);
    } else {
      this.line(depth + 1, 'tag: [');
      for (const tag of tagList) this.line(depth + 2, `${tag},`);
      this.line(depth + 1, '],');
    }
    this.line(depth, '},');
  }

  /** `key: ['a', 'b'],` on one line if it fits, else one string per line. */
  stringArrayProperty(depth: number, key: string, values: readonly string[]): void {
    const items = values.map((value) => this.q(value));
    const flat = `${key}: [${items.join(', ')}],`;
    if (this.fits(depth, flat)) {
      this.line(depth, flat);
      return;
    }
    this.line(depth, `${key}: [`);
    for (const item of items) this.line(depth + 1, `${item},`);
    this.line(depth, '],');
  }

  /** `{ a, b },` on one line if it fits, else one entry per line. */
  inlineOrBrokenObject(depth: number, prefix: string, entries: string[], suffix = ','): void {
    const flat = entries.length === 0 ? '{}' : `{ ${entries.join(', ')} }`;
    if (this.fits(depth, `${prefix}${flat}${suffix}`)) {
      this.line(depth, `${prefix}${flat}${suffix}`);
      return;
    }
    this.line(depth, `${prefix}{`);
    for (const entry of entries) this.line(depth + 1, `${entry},`);
    this.line(depth, `}${suffix}`);
  }
}

// ---------------------------------------------------------------------------------------------
// Plans
// ---------------------------------------------------------------------------------------------

interface Position {
  line: number;
  column: number;
}

function position(location: Position): string {
  return `{ line: ${String(location.line)}, column: ${String(location.column)} }`;
}

/** The target name as written in the element definition (names are matched after `trim()`). */
function definedTargetName(def: ElementDefinition | undefined, target: string): string {
  if (def === undefined) return target;
  for (const key of def.targets.keys()) if (key.trim() === target) return key;
  return target;
}

interface BlockFixtures {
  names: string[];
  unknown: string[];
}

/**
 * The fixtures the callbacks of one block destructure (screen `open`, the `fn` of the screen's
 * background conditions and of the block's conditions, the element's
 * `self` / target locators): the same analysis as the runtime's `collectFixtureNames(plan)`, done on
 * the resolved definitions. A callback whose first parameter is not destructured is `unknown`;
 * the test then requests `page` for it.
 */
function blockFixtures(
  screen: ResolvedScreen,
  element: ResolvedElement,
  condition: ResolvedCondition | undefined,
  expectations: readonly ResolvedExpectation[],
): BlockFixtures {
  const names = new Set<string>();
  const unknown: string[] = [];
  // eslint-disable-next-line @typescript-eslint/no-unsafe-function-type
  const add = (label: string, fn: Function | undefined): void => {
    if (!fn) return;
    const found = fixtureNamesOf(fn);
    if (found === undefined) unknown.push(label);
    else for (const name of found) names.add(name);
  };
  add(`screen "${screen.name}" open`, screen.definition?.open);
  for (const ref of screen.background) add(`condition "${ref.name}"`, ref.definition?.fn);
  for (const ref of condition?.conditions ?? []) add(`condition "${ref.name}"`, ref.definition?.fn);
  const def = element.definition;
  if (def) {
    for (const expectation of expectations) {
      const name = expectationTarget(expectation);
      if (name !== undefined) {
        const target = definedTargetName(def, name);
        add(`element "${element.name}" target "${name}"`, def.targets.get(target));
      } else {
        add(`element "${element.name}" self`, def.self);
      }
    }
  }
  if (unknown.length > 0) names.add(FALLBACK_FIXTURE);
  // `$nimaime` is always requested separately.
  names.delete('$nimaime');
  return { names: [...names].sort(), unknown: [...new Set(unknown)] };
}

/** Destructuring entries (`page`, `'my-fixture': fixture1`) and the object passed to `run`. */
function fixtureEntries(names: readonly string[], w: Writer): { params: string[]; args: string[] } {
  const params = ['$nimaime'];
  const args: string[] = [];
  let alias = 0;
  for (const name of names) {
    if (IDENTIFIER.test(name)) {
      params.push(name);
      args.push(name);
    } else {
      alias++;
      const local = `fixture${String(alias)}`;
      params.push(`${w.q(name)}: ${local}`);
      args.push(`${w.q(name)}: ${local}`);
    }
  }
  return { params, args };
}

function expectationEntries(
  expectation: ResolvedExpectation,
  element: ResolvedElement,
  w: Writer,
): string[] {
  const entries = [`kind: ${w.q(expectation.kind)}`];
  const target = expectationTarget(expectation);
  if (target !== undefined) {
    entries.push(`target: ${w.q(definedTargetName(element.definition, target))}`);
  }
  if ('value' in expectation) {
    const { value } = expectation;
    entries.push(`value: ${typeof value === 'number' ? String(value) : w.q(value)}`);
  }
  entries.push(`location: ${position(expectation.location)}`);
  return entries;
}

function writeExpectations(
  w: Writer,
  depth: number,
  element: ResolvedElement,
  expectations: readonly ResolvedExpectation[],
): void {
  const items = expectations.map((e) => expectationEntries(e, element, w));
  const flatItems = items.map((entries) => `{ ${entries.join(', ')} }`);
  // Prettier always breaks an array of more than one object literal with several properties.
  if (flatItems.length === 1 && w.fits(depth, `expectations: [${flatItems[0] ?? ''}],`)) {
    w.line(depth, `expectations: [${flatItems[0] ?? ''}],`);
    return;
  }
  w.line(depth, 'expectations: [');
  for (const [index, entries] of items.entries()) {
    const flat = `${flatItems[index] ?? ''},`;
    if (w.fits(depth + 1, flat)) {
      w.line(depth + 1, flat);
      continue;
    }
    w.line(depth + 1, '{');
    for (const entry of entries) {
      const long = /^(target|value): (.*)$/.exec(entry);
      if (long && !w.fits(depth + 2, `${entry},`)) {
        w.line(depth + 2, `${long[1] ?? ''}:`);
        w.line(depth + 3, `${long[2] ?? ''},`);
      } else {
        w.line(depth + 2, `${entry},`);
      }
    }
    w.line(depth + 1, '},');
  }
  w.line(depth, '],');
}

/** A `locations` property: one position, or an array of positions. */
type LocationEntry = [key: string, value: string | string[]];

/**
 * `locations: { screen: {…}, element: {…}, conditions: [{…}] },` laid out like Prettier: flat when
 * it fits, else one property per line. An array of more than one position object always breaks
 * (Prettier's rule for arrays of objects with several properties), and so does the object
 * around it.
 */
function writeLocations(w: Writer, depth: number, entries: LocationEntry[]): void {
  const flatValue = (value: string | string[]): string =>
    typeof value === 'string' ? value : `[${value.join(', ')}]`;
  const forced = entries.some(([, value]) => Array.isArray(value) && value.length > 1);
  const flat = `locations: { ${entries.map(([key, value]) => `${key}: ${flatValue(value)}`).join(', ')} },`;
  if (!forced && w.fits(depth, flat)) {
    w.line(depth, flat);
    return;
  }
  w.line(depth, 'locations: {');
  for (const [key, value] of entries) {
    const line = `${key}: ${flatValue(value)},`;
    if (typeof value === 'string' || (value.length <= 1 && w.fits(depth + 1, line))) {
      w.line(depth + 1, line);
      continue;
    }
    w.line(depth + 1, `${key}: [`);
    for (const item of value) w.line(depth + 2, `${item},`);
    w.line(depth + 1, '],');
  }
  w.line(depth, '},');
}

function writeTest(
  w: Writer,
  depth: number,
  title: string,
  screen: ResolvedScreen,
  element: ResolvedElement,
  condition: ResolvedCondition | undefined,
  expectations: readonly ResolvedExpectation[],
  fixtures: BlockFixtures,
  tags: readonly string[],
): void {
  const { params, args } = fixtureEntries(fixtures.names, w);
  const body = (d: number): void => {
    w.line(d, 'await $nimaime.run(');
    w.inlineOrBrokenObject(d + 1, '', args);
    w.line(d + 1, '{');
    const p = d + 2;
    w.stringProperty(p, 'screen', screen.definition?.name ?? screen.name);
    w.stringProperty(p, 'element', element.definition?.name ?? element.name);
    const definedName = (ref: ResolvedConditionRef): string => ref.definition?.name ?? ref.name;
    if (screen.background.length > 0) {
      w.stringArrayProperty(p, 'background', screen.background.map(definedName));
    }
    if (condition) w.stringArrayProperty(p, 'conditions', condition.conditions.map(definedName));
    writeExpectations(w, p, element, expectations);
    w.line(p, 'file,');
    const locations: LocationEntry[] = [
      ['screen', position(screen.location)],
      ['element', position(element.location)],
    ];
    if (screen.background.length > 0) {
      locations.push(['background', screen.background.map((ref) => position(ref.location))]);
    }
    if (condition) {
      locations.push(['conditions', condition.conditions.map((ref) => position(ref.location))]);
    }
    writeLocations(w, p, locations);
    w.line(d + 1, '},');
    w.line(d, ');');
  };
  w.callWithCallback(depth, 'test', title, { async: true, names: params }, body, tags);
}

// ---------------------------------------------------------------------------------------------
// Hooks (docs/hooks.md)
// ---------------------------------------------------------------------------------------------

/** `{ screen: 'X', element: 'Y' }`, broken one property per line when it does not fit. */
function writeStringObject(w: Writer, depth: number, entries: [string, string][]): void {
  const flat = `{ ${entries.map(([key, value]) => `${key}: ${w.q(value)}`).join(', ')} },`;
  if (w.fits(depth, flat)) {
    w.line(depth, flat);
    return;
  }
  w.line(depth, '{');
  for (const [key, value] of entries) w.stringProperty(depth + 1, key, value);
  w.line(depth, '},');
}

/**
 * `test.beforeAll(async ({ browser }) => { await runHooks('beforeScreen', { browser }, info); });`
 * laid out like Prettier: when the callback head does not fit after `test.beforeAll(`, the
 * callback moves to its own line, and its destructured parameter breaks if it still does not fit.
 */
function writeHook(
  w: Writer,
  depth: number,
  playwrightHook: string,
  kind: string,
  call: HookCall,
  info: [string, string][],
): void {
  const { params, args } = fixtureEntries(call.fixtures, w);
  const names = params.slice(1); // without `$nimaime`
  const flatParams = names.length === 0 ? '({})' : `({ ${names.join(', ')} })`;
  const head = `test.${playwrightHook}(async ${flatParams} => {`;
  let body = depth + 1;
  if (w.fits(depth, head)) {
    w.line(depth, head);
  } else {
    w.line(depth, `test.${playwrightHook}(`);
    if (w.fits(depth + 1, `async ${flatParams} => {`)) {
      w.line(depth + 1, `async ${flatParams} => {`);
    } else {
      w.line(depth + 1, 'async ({');
      for (const name of names) w.line(depth + 2, `${name},`);
      w.line(depth + 1, '}) => {');
    }
    body = depth + 2;
  }
  const fixturesFlat = args.length === 0 ? '{}' : `{ ${args.join(', ')} }`;
  const infoFlat = `{ ${info.map(([key, value]) => `${key}: ${w.q(value)}`).join(', ')} }`;
  const flatCall = `await runHooks(${w.q(kind)}, ${fixturesFlat}, ${infoFlat});`;
  if (w.fits(body, flatCall)) {
    w.line(body, flatCall);
  } else {
    w.line(body, 'await runHooks(');
    w.line(body + 1, `${w.q(kind)},`);
    w.inlineOrBrokenObject(body + 1, '', args);
    writeStringObject(w, body + 1, info);
    w.line(body, ');');
  }
  if (body === depth + 1) {
    w.line(depth, '});');
  } else {
    w.line(depth + 1, '},');
    w.line(depth, ');');
  }
}

/**
 * The `test.beforeAll` / `test.afterAll` (screen) or `test.beforeEach` / `test.afterEach`
 * (element) calls of one scope. Returns whether anything was written. `info` carries the names
 * as written in the spec (hooks are matched by name, not bound to a definition).
 */
function writeScopeHooks(
  w: Writer,
  depth: number,
  scope: HookUsage | undefined,
  info: { screen: string; element?: string },
  titlePath: string[],
  unknownFixtures: UnknownFixtures[],
): boolean {
  if (!scope || !hasHooks(scope)) return false;
  const element = info.element !== undefined;
  const entries: [string, string][] = [['screen', info.screen]];
  if (info.element !== undefined) entries.push(['element', info.element]);
  const sides = [
    [
      element ? 'beforeEach' : 'beforeAll',
      element ? 'beforeElement' : 'beforeScreen',
      scope.before,
    ],
    [element ? 'afterEach' : 'afterAll', element ? 'afterElement' : 'afterScreen', scope.after],
  ] as const;
  let first = true;
  for (const [playwrightHook, kind, call] of sides) {
    if (!call) continue;
    if (!first) w.blank();
    first = false;
    for (const callback of call.unknown) {
      unknownFixtures.push({
        callback,
        titlePath: [...titlePath, `${playwrightHook} hook`],
        fallback: call.fallback,
      });
    }
    writeHook(w, depth, playwrightHook, kind, call, entries);
  }
  return true;
}

/** Whether any screen or element of `doc` gets generated hooks (then `runHooks` is imported). */
function documentUsesHooks(doc: ResolvedDocument, hooks: DocumentHooks | undefined): boolean {
  if (!hooks) return false;
  return doc.screens.some((screen) => {
    const usage = hooks.get(screen.name);
    return (
      hasHooks(usage) ||
      screen.elements.some((element) => hasHooks(usage?.elements.get(element.name)))
    );
  });
}

// ---------------------------------------------------------------------------------------------
// Files
// ---------------------------------------------------------------------------------------------

/**
 * The tags to put on a node: its own, without those an enclosing describe already has (Playwright
 * adds the tags of enclosing describes to a test).
 */
function ownTags(tags: readonly Tag[], inherited: readonly (readonly Tag[])[]): string[] {
  const outer = new Set(tagNames(...inherited));
  return tagNames(tags).filter((tag) => !outer.has(tag));
}

/**
 * Generates the Playwright spec file of one resolved document.
 *
 * Layout: `test.describe('Screen: X')` > `test.describe('Element: Y')` > one `test()` per block:
 * `'Always'` for the element's unconditional block (its invariants, checked in the base state) and
 * `'When: C'` (`'When: C and D'` with `And when: D`) for each condition block. The plans of a
 * screen with `Background:` lines carry `background: [...]`; condition blocks carry
 * `conditions: [...]` (the `When:` condition, then each `And when:` condition). Each test destructures `$nimaime` plus the fixtures its
 * definitions use and calls `$nimaime.run(fixtures, plan)`; plans carry the `.sanmaime` file
 * (relative to the generated file) and the line/column of every Screen/Element/When/expectation.
 *
 * Names in plans are the names as defined (definitions are matched after `trim()`, the runtime
 * looks them up exactly); titles use the names as written in the spec.
 */
export function generateSpecFile(
  doc: ResolvedDocument,
  options: GenerateOptions,
): GeneratedSpecFile {
  const outFile = generatedSpecPath(doc.file, options.configDir, options.outputDir);
  const outDir = path.dirname(outFile);
  const w = new Writer(options.quotes);
  const tests: GeneratedTest[] = [];
  const unknownFixtures: UnknownFixtures[] = [];

  w.line(0, `${GENERATED_HEADER_PREFIX} from ${doc.uri}. Do not edit.`);
  const runtimeImports = documentUsesHooks(doc, options.hooks)
    ? 'createNimaimeTest, runHooks'
    : 'createNimaimeTest';
  w.line(0, `import { ${runtimeImports} } from ${w.q(RUNTIME_MODULE)};`);
  const custom = options.importTestFrom;
  if (custom) {
    const binding = custom.varName === 'base' ? 'base' : `${custom.varName} as base`;
    w.line(0, `import { ${binding} } from ${w.q(importSpecifier(outDir, custom.file))};`);
  } else {
    w.line(0, `import { test as base } from ${w.q('@playwright/test')};`);
  }
  const imported = new Set<string>(custom ? [path.resolve(custom.file)] : []);
  for (const file of options.definitionFiles) {
    const abs = path.resolve(file);
    if (imported.has(abs)) continue;
    imported.add(abs);
    w.line(0, `import ${w.q(importSpecifier(outDir, abs))};`);
  }
  w.blank();
  w.line(0, 'const test = createNimaimeTest(base);');
  const fileLiteral = w.q(path.relative(outDir, doc.file).split(path.sep).join('/'));
  if (w.fits(0, `const file = ${fileLiteral};`)) {
    w.line(0, `const file = ${fileLiteral};`);
  } else {
    w.line(0, 'const file =');
    w.line(1, `${fileLiteral};`);
  }

  for (const screen of doc.screens) {
    // Tags go on the node that has them (Playwright adds the tags of enclosing describes).
    const screenTitle = `Screen: ${screen.name}`;
    w.blank();
    w.callWithCallback(
      0,
      'test.describe',
      screenTitle,
      { async: false, names: undefined },
      (d1) => {
        const screenHooks = options.hooks?.get(screen.name);
        const wroteScreenHooks = writeScopeHooks(
          w,
          d1,
          screenHooks,
          { screen: screen.name },
          [screenTitle],
          unknownFixtures,
        );
        screen.elements.forEach((element, elementIndex) => {
          if (elementIndex > 0 || wroteScreenHooks) w.blank();
          const elementTitle = `Element: ${element.name}`;
          w.callWithCallback(
            d1,
            'test.describe',
            elementTitle,
            { async: false, names: undefined },
            (d2) => {
              const wroteElementHooks = writeScopeHooks(
                w,
                d2,
                screenHooks?.elements.get(element.name),
                { screen: screen.name, element: element.name },
                [screenTitle, elementTitle],
                unknownFixtures,
              );
              const blocks: {
                title: string;
                condition: ResolvedCondition | undefined;
                expectations: readonly ResolvedExpectation[];
                tags: string[];
              }[] = [];
              if (element.unconditional.length > 0) {
                blocks.push({
                  title: UNCONDITIONAL_TEST_TITLE,
                  condition: undefined,
                  expectations: element.unconditional,
                  tags: [],
                });
              }
              for (const condition of element.conditions) {
                blocks.push({
                  title: conditionTestTitle(condition),
                  condition,
                  expectations: condition.expectations,
                  tags: ownTags(condition.tags, [screen.tags, element.tags]),
                });
              }
              blocks.forEach((block, blockIndex) => {
                if (blockIndex > 0 || wroteElementHooks) w.blank();
                const titlePath = [screenTitle, elementTitle, block.title];
                const fixtures = blockFixtures(
                  screen,
                  element,
                  block.condition,
                  block.expectations,
                );
                for (const callback of fixtures.unknown)
                  unknownFixtures.push({ callback, titlePath });
                tests.push({
                  titlePath,
                  tags: tagNames(screen.tags, element.tags, block.condition?.tags ?? []),
                });
                writeTest(
                  w,
                  d2,
                  block.title,
                  screen,
                  element,
                  block.condition,
                  block.expectations,
                  fixtures,
                  block.tags,
                );
              });
            },
            ownTags(element.tags, [screen.tags]),
          );
        });
      },
      tagNames(screen.tags),
    );
  }

  return { path: outFile, content: `${w.lines.join('\n')}\n`, tests, unknownFixtures };
}

/** The title paths of the tests `generateSpecFile(doc)` generates (for `nimaime-gen export`). */
export function listTests(doc: ResolvedDocument): GeneratedTest[] {
  const tests: GeneratedTest[] = [];
  for (const screen of doc.screens) {
    for (const element of screen.elements) {
      const prefix = [`Screen: ${screen.name}`, `Element: ${element.name}`];
      if (element.unconditional.length > 0) {
        tests.push({
          titlePath: [...prefix, UNCONDITIONAL_TEST_TITLE],
          tags: tagNames(screen.tags, element.tags),
        });
      }
      for (const condition of element.conditions) {
        tests.push({
          titlePath: [...prefix, conditionTestTitle(condition)],
          tags: tagNames(screen.tags, element.tags, condition.tags),
        });
      }
    }
  }
  return tests;
}
